PAIRS = {')': '(', ']': '[', '}': '{', '>': '<'}
OPEN = set(PAIRS.values())
CLOSE = {v: k for k, v in PAIRS.items()}

def scan(toks):
    """Stack-scan a token list. Returns (status, index, detail, open_stack)."""
    stack = []
    for i, t in enumerate(toks):
        if t in OPEN:
            stack.append(t)
        elif t in PAIRS:
            if not stack:
                return ('EXTRA_CLOSE', i, t, stack)
            top = stack.pop()
            if top != PAIRS[t]:
                return ('MISMATCH', i, f'{t} vs open {top}', stack)
        else:
            return ('BAD_TOKEN', i, t, stack)
    return ('OK', None, None, stack)

def minimal_completion(open_stack):
    # Unique shortest closing suffix: close the most recent open bracket first.
    return [CLOSE[o] for o in reversed(open_stack)]

INPUT = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
