in_toks = INPUT.split()
sub_toks = SUBMITTED.split()

in_status, in_idx, in_detail, in_stack = scan(in_toks)
print("input scan:", in_status, "open stack (bottom->top):", in_stack)

expected_suffix = minimal_completion(in_stack) if in_status == 'OK' else None
print("expected completion suffix:", " ".join(expected_suffix) if expected_suffix else "UNSUPPORTED")

expected_toks = in_toks + (expected_suffix or [])
expected_str = " ".join(expected_toks)
